
const $=s=>document.querySelector(s);const money=n=>Number(n).toLocaleString('ko-KR');let scene=0,quantity=1,saved=false,method='잇담 결제',paySource='direct';let cart=[{id:1,name:'국내산 배추 1포기',store:'홍길네 채소가게',photo:'cabbage-seller.png',price:1500,old:2500,qty:1,stock:7,selected:true},{id:2,name:'손질 고등어 2마리',store:'형래네 생선가게',photo:'mackerel-seller.png',price:4500,old:7000,qty:1,stock:5,selected:true},{id:3,name:'수제 두부 1모',store:'시장 두부가게',photo:'tofu-seller.png',price:2100,old:3000,qty:1,stock:8,selected:true}];const titles=['상품 정보 확인','구매 수량 선택','장바구니 담기','장바구니 확인','결제 수단 선택'];function totals(){return cart.filter(p=>p.selected).reduce((a,p)=>({price:a.price+p.price*p.qty,old:a.old+p.old*p.qty,count:a.count+p.qty}),{price:0,old:0,count:0})}function toast(t){$('.toast').textContent=t;$('.toast').classList.remove('hidden');setTimeout(()=>$('.toast').classList.add('hidden'),2200)}function action(t,fn){$('#action').innerHTML=`<button class="primary">${t}</button>`;$('#action button').onclick=fn;$('#content').classList.add('has-action')}function go(n){scene=n;if(n===4&&paySource==='cart'&&!totals().count){toast('결제할 상품을 선택해주세요.');scene=3}render()}function detail(){return `<div class="photo-wrap"><img class="hero" src="assets/cabbage-seller.png" alt="판매 상품 배추 사진 예시"><button class="heart" aria-label="관심 상품 저장" aria-pressed="${saved}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20.3s-7.5-4.6-7.5-10.1A4.2 4.2 0 0 1 12 7.6a4.2 4.2 0 0 1 7.5 2.6c0 5.5-7.5 10.1-7.5 10.1Z"/></svg></button></div><div class="badge-line"><span>국내산 · 채소</span><span>서원시장 · 도보 약 10분</span></div><h1 class="product-name">국내산 배추</h1><div class="shop-info"><div><b class="shop-link">홍길네 채소가게<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></b><p>영업시간 09:00–19:00</p></div><span>100°</span></div><p class="old-price">2,500원</p><div class="detail-price"><em>40%</em><b>1,500원</b><small>/ 1포기</small></div><p class="stock-line">지금 구매할 수 있는 수량 7포기</p><p class="description">오늘 들어온 국내산 배추예요.<br>겉잎까지 싱싱하게 보관했어요.</p><div class="pickup-note">서원시장 내 홍길네 채소가게에서 수령해요.<br>방문 전 영업시간과 구매 수량을 확인해주세요.</div>`}function render(){const c=$('#content');c.classList.remove('has-action');$('#layer').innerHTML='';$('.head b').textContent=scene===3?'장바구니':scene===4?'결제 수단 선택':'상품 상세';$('.steps').innerHTML=titles.map((t,i)=>`<button class="${scene===i?'on':''}" data-scene="${i}">0${i+1}　${t}</button>`).join('');document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{if(+b.dataset.scene===4)paySource='direct';go(+b.dataset.scene)});
if(scene<3){c.innerHTML=detail();$('.heart').onclick=()=>{saved=!saved;$('.heart').setAttribute('aria-pressed',saved)};action('수량 선택하기',()=>go(1));if(scene===1){$('#layer').innerHTML=`<div class="overlay"><section class="sheet-purchase" role="dialog" aria-modal="true" aria-label="구매 수량 선택"><div class="handle"></div><div class="sheet-top"><h2>국내산 배추</h2><button id="close" aria-label="수량 선택 닫기">×</button></div><p class="sheet-store">홍길네 채소가게 · 1포기 기준</p><div class="counter"><button id="minus" aria-label="수량 줄이기" ${quantity===1?'disabled':''}>−</button><b>${quantity}</b><button id="plus" aria-label="수량 늘리기" ${quantity===7?'disabled':''}>＋</button></div><p class="qty-info">최대 7포기까지 구매할 수 있어요</p><div class="sheet-total"><span>상품 금액</span><b>${money(quantity*1500)}원</b></div><div class="sheet-buttons"><button class="outline" id="add">장바구니 담기</button><button class="primary" id="buy">바로 구매</button></div></section></div>`;$('#minus').onclick=()=>{quantity=Math.max(1,quantity-1);render()};$('#plus').onclick=()=>{quantity=Math.min(7,quantity+1);render()};$('#close').onclick=()=>go(0);$('#add').onclick=()=>{cart[0].qty=quantity;cart[0].selected=true;go(2)};$('#buy').onclick=()=>{paySource='direct';go(4)}}if(scene===2){$('#layer').innerHTML=`<div class="overlay"><section class="confirm-box" role="dialog" aria-modal="true" aria-label="장바구니 담기 완료"><div class="check-circle"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5 10 17.5 19 7.5"/></svg></div><h2>장바구니에 담았어요</h2><p>국내산 배추 ${quantity}포기 · ${money(quantity*1500)}원</p><button class="primary" id="view-cart">장바구니 확인하기</button><button class="secondary" id="continue">계속 쇼핑하기</button></section></div>`;$('#view-cart').onclick=()=>go(3);$('#continue').onclick=()=>go(0)}}
if(scene===3){const t=totals();c.innerHTML=`<p class="eyebrow">내가 고른 시장의 상품</p><h1>장바구니</h1><div class="total"><div><span>선택 상품 금액</span><strong>${money(t.price)}원</strong></div><p>정가 ${money(t.old)}원에서 ${money(t.old-t.price)}원을 아껴요</p></div><div class="cart-header"><b>서원시장</b><label><input type="checkbox" id="all" ${cart.every(p=>p.selected)?'checked':''}>전체 선택</label></div>${cart.map(p=>`<article class="cart-item"><input type="checkbox" data-check="${p.id}" aria-label="${p.name} 선택" ${p.selected?'checked':''}><img src="assets/${p.photo}" alt="${p.name}"><div class="item-copy"><h3>${p.name}</h3><p>${p.store}</p><strong>${money(p.price*p.qty)}원</strong><div class="small-counter"><button data-minus="${p.id}" aria-label="${p.name} 수량 줄이기">−</button><span>${p.qty}</span><button data-plus="${p.id}" aria-label="${p.name} 수량 늘리기">＋</button></div></div></article>`).join('')}<p class="demo-alert">장바구니에는 비교를 위한 예시 상품이 포함되어 있어요. 각 점포에서 상품을 수령합니다.</p>`;$('#all').onchange=e=>{cart.forEach(p=>p.selected=e.target.checked);refresh()};document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{cart.find(p=>p.id===+b.dataset.check).selected=b.checked;refresh()});document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{const p=cart.find(p=>p.id===+b.dataset.minus);p.qty=Math.max(1,p.qty-1);refresh()});document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{const p=cart.find(p=>p.id===+b.dataset.plus);p.qty=Math.min(p.stock,p.qty+1);refresh()});action(t.count?'선택 상품 '+money(t.price)+'원 결제하기':'결제할 상품을 선택해주세요',()=>{if(!t.count){toast('상품을 하나 이상 선택해주세요.');return}paySource='cart';go(4)})}
if(scene===4){const t=paySource==='cart'?totals():{price:quantity*1500,old:quantity*2500,count:quantity};c.innerHTML=`<p class="eyebrow">주문 전 마지막 확인</p><h1>결제 방법을 골라주세요</h1><p class="intro">${paySource==='cart'?'선택한 상품 '+t.count+'개':'국내산 배추 '+quantity+'포기'}</p><div class="pay-summary"><div><span>할인 전 금액</span><b>${money(t.old)}원</b></div><div><span>할인 금액</span><b>−${money(t.old-t.price)}원</b></div><div><span>최종 상품 금액</span><b>${money(t.price)}원</b></div></div>${['잇담 결제','KakaoPay','카드 등록하기','현장에서 결제하기'].map(m=>`<button class="pay-method ${method===m?'selected':''}" data-method="${m}" aria-pressed="${method===m}">${m}<span>${method===m?'✓':'○'}</span></button>`).join('')}<p class="demo-alert">결제 수단 선택을 확인하는 프로토타입입니다. 실제 카드 정보 입력이나 결제는 진행되지 않습니다.<br>현장 결제 시에는 점포에서 결제와 수령 조건을 확인해주세요.</p>`;document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{method=b.dataset.method;refresh()});action('선택한 결제 방법 확인',()=>toast(method+' 선택을 확인했어요. 실제 결제는 진행되지 않습니다.'))}c.scrollTop=0}
function refresh(){const y=$('#content').scrollTop;render();$('#content').scrollTop=y}$('.back').onclick=()=>go([0,0,0,0,paySource==='cart'?3:1][scene]);$('.cart-open').onclick=()=>go(3);document.querySelectorAll('.nav button').forEach((b,i)=>{b.classList.remove('active');b.onclick=()=>toast('상품 확인과 구매 흐름을 체험하는 시안입니다.')});render();
